def run_expedition7_whole_slide_spatial_secretome(
    random_state: int = 42,
    output_path: Optional[str | Path] = None,
) -> Dict[str, Any]:
    """
    Execute the complete Expedition 7 Whole-Slide 17,138-Gene Spatial Secretome &
    Multi-Slide cSCC Replicate Discovery pipeline and serialize strict JSON
    results (`allow_nan=False`, `indent=2`).
    """
    scanner = WholeSlideSpatialSecretomeScanner(random_state=random_state)
    results = scanner.run_full_scan()

    if output_path is None:
        repo_root = Path(__file__).resolve().parents[2]
        output_path = repo_root / "results" / "expedition7_whole_slide_spatial_secretome.json"
    else:
        output_path = Path(output_path)

    output_path.parent.mkdir(parents=True, exist_ok=True)
    json_payload = json.dumps(results, indent=2, allow_nan=False)
    output_path.write_text(json_payload, encoding="utf-8")
    return results


if __name__ == "__main__":
    res = run_expedition7_whole_slide_spatial_secretome(random_state=42)
    print(
        f"[Expedition 7] Scan complete. All adversarial tests passed: {res['all_adversarial_tests_passed']}"
    )
